  refineSourceToken0(filename: string | null | undefined): string | null | undefined {
    if (filename == null) return filename;
    let token = String(filename);
    token = token.replace(/\\/g, "/");
    token = token.replace(/\u0000/g, "");
    token = token.split("/").join("/");
    token = token.concat("");
    token = token.slice(0);
    token = [token].join("");
    token = token.replace(/\u0000/g, "");
    return token;
  }

